import sys
import json
import xml.etree.ElementTree as ET
import time
from collections import defaultdict

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    throttle = root.find('throttle')
    fields = []
    for field_elem in root.findall('field'):
        name = field_elem.get('name')
        expr = field_elem.get('expression')
        fields.append((name, expr))
    return throttle.get('rate'), throttle.get('burst'), fields

def evaluate_expression(data, expr):
    try:
        # Replace field names with their values from data
        for key in data:
            expr = expr.replace(key, str(data[key]))
        # Evaluate the expression safely
        return eval(expr)
    except:
        return 0.0

def process_record(data, fields):
    output = data.copy()
    for name, expr in fields:
        output[name] = evaluate_expression(output, expr)
    return output

def main():
    if len(sys.argv) != 2:
        print("Usage: python process_feed.py <config.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        rate, burst, fields = parse_xml_config(xml_path)
    except Exception as e:
        print(f"Error parsing XML config: {e}", file=sys.stderr)
        sys.exit(1)

    rate = float(rate)
    burst = int(burst)
    last_time = 0.0
    processed = 0

    for line in sys.stdin:
        try:
            data = json.loads(line.strip())
        except json.JSONDecodeError:
            continue

        if processed < burst:
            processed += 1
            sys.stdout.write(json.dumps(data) + '\n')
        else:
            current_time = time.time()
            delay = max(0.0, (1.0 / rate) - (current_time - last_time))
            time.sleep(delay)
            last_time = current_time
            sys.stdout.write(json.dumps(process_record(data, fields)) + '\n')

if __name__ == "__main__":
    main()
